head.script:
scwin.screenId = "jlddst11000";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "cal_selDate", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("selDate")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    /* sdd-asis-lifecycle:begin init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
    //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
    //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
    console.warn('[sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates(' + "1" + ')');
    await scwin.fnSearchInit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.init();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst11000.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst11000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.searchForm_onsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.searchForm_onsubmit = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin searchForm_onsubmit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst11000.searchForm_onsubmit' }); }
};

/**
 * @event
 * @name scwin.btn_findCompanyName_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_findCompanyName_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_findCompanyName_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }); return false;
    /* sdd-asis-lifecycle:end */

} catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst11000.btn_findCompanyName_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_fnSearchCorpName_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnSearchCorpName_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnSearchCorpName_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnSearchCorpName(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst11000.btn_fnSearchCorpName_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_fnDownload_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_fnDownload_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnDownload_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnDownload(); return false;
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst11000.btn_fnDownload_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/corpdetail/ventureFundInvest.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst11000.tx_fnDownload" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fnSearch_ajaxsubmit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/corpdetail/ventureFundInvest.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst11000.tx_fnSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.keyEvent
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.keyEvent = async function (e) {
    /* sdd-asis-lifecycle:begin keyEvent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) == 13 || (typeof e !== 'undefined' && e == 13)) {
        if ($c.util.getKeyCode(event) == 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('AKCKwd')))) {
                await scwin.fnSearchCorpName();
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchInit
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchInit = async function () {
    /* sdd-asis-lifecycle:begin fnSearchInit — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.fnOrder("1", "A");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch1
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch1 = async function () {
    /* sdd-asis-lifecycle:begin fnSearch1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnOrder
 * @author Inswave
 * @date 2026. 09. 29
 * @param mode stat
 * @returns
 * @hidden N
*/
scwin.fnOrder = async function (mode, stat) {
    /* sdd-asis-lifecycle:begin fnOrder — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpName
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpName = async function () {
    /* sdd-asis-lifecycle:begin fnSearchCorpName — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("searchMode", "1");
    let val = $c.util.getComponent('AKCKwd').getValue(); if (val == null) { val = ''; }
    if (val !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
        Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
} else {
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
    await scwin.fnSearchInit();
}
/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpNameAllCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param items
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    /* sdd-asis-lifecycle:begin fnSearchCorpNameAllCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (items.length == 1) {
        await scwin.fnSearchCorpCode(items[0].repisusrtcd);
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSearchCorpCode('');
    }
}
/* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCorpCode
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_repIsuSrtCd
 * @returns
 * @hidden N
*/
scwin.fnSearchCorpCode = async function (ipt_repIsuSrtCd) {
    /* sdd-asis-lifecycle:begin fnSearchCorpCode — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (ipt_repIsuSrtCd === "") {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", '');
        const val = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
    } else {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", ipt_repIsuSrtCd);
        await scwin.fnSearch();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd kisComCd ipt_repIsuSrtCd comNm comAbbrv isurSymbl fssUnqNo
 * @returns
 * @hidden N
*/
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "A" + ipt_repIsuSrtCd);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchCorpListSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "corpListSub");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
    console.warn('[sdd] 미실현(재설계 분류 #128): fnLegendTooltip(' + "" + ')');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    $("#searchForm").attr('onsubmit', '');
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchCorpListSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "corpListExcel");
    await scwin.tx_fnDownload();
    $("#searchForm").attr('onsubmit', 'return false;');
    /* sdd-asis-lifecycle:end */
};
